'use strict';
function jiraIssuesForMode(mode){const issues=jiraScope?.issues||[];if(mode==='focus')return issues.filter(i=>HistoryCore.focus.includes(i.section));const section={req:'Feature Requirements',docs:'Dev. Spec. Documents',validation:'SW Validation'}[mode];return issues.filter(i=>i.section===section);}
function statusDonut(rows,mode){
 if(jiraScope?.issues?.length){const issues=jiraIssuesForMode(mode),names=['To Do','In Progress','Pre-silicon Done','Resolved','Reopened','Done'],palette=['#c6ceda','#7c3aed','#638ac7','#409776','#f97316','#0b7f79'],norm=s=>{const x=String(s||'').toLowerCase();return x.includes('progress')?'In Progress':x.includes('pre-silicon')||x==='p-d'?'Pre-silicon Done':x==='resolved'?'Resolved':x.includes('reopen')?'Reopened':x==='done'||x==='closed'?'Done':'To Do'},counts=Object.fromEntries(names.map(n=>[n,issues.filter(i=>norm(i.currentStatus)===n).length])),entries=names.filter(n=>counts[n]),circ=2*Math.PI*58;let offset=0;const rings=entries.map(n=>{const len=counts[n]/Math.max(1,issues.length)*circ,part=`<circle cx="80" cy="80" r="58" fill="none" stroke="${palette[names.indexOf(n)]}" stroke-width="23" stroke-dasharray="${Math.max(0,len-(entries.length>1?2:0))} ${circ}" stroke-dashoffset="${-offset}" transform="rotate(-90 80 80)"><title>${n}: ${counts[n]} (${Math.round(counts[n]/Math.max(1,issues.length)*100)}%)</title></circle>`;offset+=len;return part}).join('');return `<div class="donut-wrap"><svg class="donut" viewBox="0 0 160 160" role="img" aria-label="Jira status distribution for ${esc(Analytics.scopes[mode].title)}"><circle cx="80" cy="80" r="58" fill="none" stroke="#edf1f6" stroke-width="23"/>${rings}<text x="80" y="79" text-anchor="middle" class="donut-number">${issues.length}</text><text x="80" y="100" text-anchor="middle" class="donut-unit">Jira tickets</text></svg></div><div class="donut-legend">${entries.map(n=>`<div class="donut-static"><i style="background:${palette[names.indexOf(n)]}"></i><span>${n}</span><b>${counts[n]}</b><small>${Math.round(counts[n]/Math.max(1,issues.length)*100)}%</small></div>`).join('')||'<p>No filter tickets in this section.</p>'}</div>`;}
 const counts=Analytics.countStatus(rows),entries=Object.entries(counts).filter(([,n])=>n),circ=2*Math.PI*58;let offset=0;
 const rings=entries.map(([k,n])=>{const len=n/rows.length*circ,part=`<a href="#results" data-cohort="${mode}" data-drill-status="${esc(k)}" aria-label="${esc(Plan.labels[k]||k)}: ${n} supporting entries in ${esc(Analytics.scopes[mode].title)}"><circle cx="80" cy="80" r="58" fill="none" stroke="${colors[k]||'#8493a8'}" stroke-width="23" stroke-dasharray="${Math.max(0,len-(entries.length>1?2:0))} ${circ}" stroke-dashoffset="${-offset}" transform="rotate(-90 80 80)"><title>${esc(Plan.labels[k]||k)}: ${n} (${Math.round(n/rows.length*100)}%)</title></circle></a>`;offset+=len;return part}).join('');
 return `<div class="donut-wrap"><svg class="donut" viewBox="0 0 160 160" role="group" aria-label="Status distribution for ${esc(Analytics.scopes[mode].title)}"><circle cx="80" cy="80" r="58" fill="none" stroke="#edf1f6" stroke-width="23"/>${rings}<text x="80" y="79" text-anchor="middle" class="donut-number">${rows.length}</text><text x="80" y="100" text-anchor="middle" class="donut-unit">supporting entries</text></svg></div><div class="donut-legend">${entries.map(([k,n])=>`<button data-cohort="${mode}" data-drill-status="${esc(k)}"><i style="background:${colors[k]||'#8493a8'}"></i><span>${esc(Plan.labels[k]||k)}</span><b>${n}</b><small>${Math.round(n/rows.length*100)}%</small></button>`).join('')||'<p>No supporting entries in this section.</p>'}</div>`;
}
function jiraStatusSummary(mode){
 const issues=jiraIssuesForMode(mode),keys=new Set(issues.map(i=>i.key));
 const names=['To Do','In Progress','Pre-silicon Done','Resolved','Reopened','Done'],palette=['#dc2626','#7c3aed','#2563eb','#16a34a','#f97316','#0891b2'];
 const norm=s=>{const x=String(s||'').toLowerCase();return x.includes('progress')?'In Progress':x.includes('pre-silicon')||x==='p-d'?'Pre-silicon Done':x==='resolved'?'Resolved':x.includes('reopen')?'Reopened':x==='done'||x==='closed'?'Done':'To Do'};
 let events=[];for(const i of issues)if(i.created)events.push({day:i.created.slice(0,10),status:'To Do'});for(const c of (jiraScope.changes||[]))if(keys.has(c.key)&&c.field==='status'&&c.at)events.push({day:c.at.slice(0,10),status:norm(c.to)});const range=historyState.cumulativeRange,latest=Date.parse(jiraScope.observedAt||new Date().toISOString()),cutoff=range==='all'?0:latest-Number(range)*86400000;events=events.filter(e=>Date.parse(e.day)>=cutoff);
 const days=[...new Set(events.map(e=>e.day))].sort();if(!days.length)return `<details class="status-cumulative"><summary>Cumulative Jira status chart · ${issues.length} tickets</summary><p class="chart-footnote">No Jira history events are available.</p></details>`;
 const daily=Object.fromEntries(names.map(n=>[n,days.map(d=>events.filter(e=>e.day===d&&e.status===n).length)])),cumulative=Object.fromEntries(names.map(n=>{let total=0;return[n,daily[n].map(v=>total+=v)]}));
 const W=620,H=250,L=38,R=12,T=18,B=38,max=Math.max(1,...names.flatMap(n=>cumulative[n])),x=i=>L+(days.length<2?(W-L-R)/2:i*(W-L-R)/(days.length-1)),y=v=>H-B-v/max*(H-T-B),slot=(W-L-R)/Math.max(days.length,1),bar=Math.max(1,Math.min(5,slot/names.length));let svg='';
 for(let j=0;j<=4;j++){const v=Math.round(max*j/4);svg+=`<line x1="${L}" y1="${y(v)}" x2="${W-R}" y2="${y(v)}" stroke="#e4e9f0"/><text x="${L-6}" y="${y(v)+4}" text-anchor="end">${v}</text>`;}
 names.forEach((n,j)=>{daily[n].forEach((v,i)=>{if(v)svg+=`<rect x="${x(i)-bar*names.length/2+j*bar}" y="${y(v)}" width="${bar}" height="${H-B-y(v)}" fill="${palette[j]}" opacity=".42"><title>${days[i]} · ${n}: ${v} event${v===1?'':'s'}</title></rect>`;});for(let i=1;i<days.length;i++)svg+=`<line x1="${x(i-1)}" y1="${y(cumulative[n][i-1])}" x2="${x(i)}" y2="${y(cumulative[n][i])}" stroke="${palette[j]}" stroke-width="2"/>`;});
 days.forEach((d,i)=>{if(i===0||i===days.length-1||i%Math.max(1,Math.ceil(days.length/6))===0)svg+=`<text x="${x(i)}" y="${H-14}" text-anchor="middle">${d.slice(5)}</text>`;});
 return `<details class="status-cumulative" open><summary>Cumulative Jira status chart · ${issues.length} tickets</summary><div class="jira-range"><label>Time frame <select data-jira-range><option value="all" ${range==='all'?'selected':''}>All ticket history</option><option value="30" ${range==='30'?'selected':''}>Last 30 days</option><option value="90" ${range==='90'?'selected':''}>Last 90 days</option><option value="180" ${range==='180'?'selected':''}>Last 180 days</option></select></label></div><p class="chart-footnote">Bars: transitions per day · lines: cumulative entries into each status · Jira filter 19455</p><div class="jira-flow-scroll"><svg class="jira-flow-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Daily and cumulative Jira status transitions">${svg}</svg></div><div class="jira-flow-legend">${names.map((n,j)=>`<span><i style="background:${palette[j]}"></i>${n}</span>`).join('')}</div></details>`;
}
function stackedBars(rows,key){
 const grouped=Analytics.groupRows(rows,key).sort((a,b)=>b.total-a.total),max=Math.max(1,...grouped.map(g=>g.total));
 return grouped.map(g=>`<div class="bar-item"><div class="bar-top"><button class="bar-label" data-drill-field="${key}" data-drill-value="${esc(g.label)}">${esc(g.label==='Not recorded'&&key==='owner'?'Unassigned':g.label)}</button><strong>${g.total}</strong></div><div class="bar-track"><div class="bar-stack" style="width:${g.total/max*100}%">${Object.entries(g.statuses).filter(([,n])=>n).map(([k,n])=>`<button data-drill-field="${key}" data-drill-value="${esc(g.label)}" data-drill-status="${esc(k)}" style="flex:${n};background:${colors[k]||'#8493a8'}" aria-label="${esc(g.label)}, ${esc(Plan.labels[k]||k)}: ${n}" title="${esc(Plan.labels[k]||k)}: ${n}"></button>`).join('')}</div></div></div>`).join('')||'<p class="empty-chart">No matching supporting entries.</p>';
}
function smallLegend(){return `<div class="chart-key">${Object.entries(Plan.labels).map(([k,label])=>`<span><i style="background:${colors[k]}"></i>${label}</span>`).join('')}</div>`}
function cumulativeCohortChart(){
 const cohorts=[['focus','Host SW features'],['req','Requirements'],['docs','Dev. Spec. Documents'],['validation','Validation plan']],issues=jiraScope?.issues||[];
 if(!issues.length)return '';
 const latest=Date.parse(jiraScope.observedAt||new Date().toISOString()),earliest=Math.min(...issues.map(i=>Date.parse(i.created)).filter(Number.isFinite)),range=historyState.cumulativeRange,cutoff=range==='all'?earliest:Math.max(earliest,latest-Number(range)*86400000),start=new Date(cutoff);start.setUTCHours(0,0,0,0);start.setUTCDate(start.getUTCDate()-((start.getUTCDay()+6)%7));
 const points=[];for(let t=start.getTime();t<=latest;t+=604800000){const end=Math.min(t+604800000-1,latest);points.push({date:new Date(end).toISOString(),values:cohorts.map(([key])=>jiraIssuesForMode(key).filter(i=>Date.parse(i.created)<=end).length)});}if(!points.length||Date.parse(points.at(-1).date)<latest)points.push({date:new Date(latest).toISOString(),values:cohorts.map(([key])=>jiraIssuesForMode(key).filter(i=>Date.parse(i.created)<=latest).length)});
 const W=980,H=300,L=58,R=24,T=24,B=48,max=Math.max(1,...points.flatMap(p=>p.values)),x=i=>L+(points.length<2?(W-L-R)/2:i*(W-L-R)/(points.length-1)),y=v=>H-B-v/max*(H-T-B);let svg='';
 for(let j=0;j<=4;j++){const v=Math.round(max*j/4);svg+=`<line x1="${L}" y1="${y(v)}" x2="${W-R}" y2="${y(v)}" stroke="#dfe7ef"/><text x="${L-10}" y="${y(v)+5}" text-anchor="end">${v}</text>`;}
 cohorts.forEach(([key,label],j)=>{const color=seriesColors[j];for(let i=0;i<points.length;i++){if(i)svg+=`<line x1="${x(i-1)}" y1="${y(points[i-1].values[j])}" x2="${x(i)}" y2="${y(points[i].values[j])}" stroke="${color}" stroke-width="3"/>`;svg+=`<circle cx="${x(i)}" cy="${y(points[i].values[j])}" r="5" fill="${color}"><title>${esc(label)} · ${new Date(points[i].date).toLocaleDateString('en-GB')}: ${points[i].values[j]} tickets</title></circle>`;}});
 points.forEach((p,i)=>{if(points.length<14||i%Math.max(1,Math.ceil(points.length/12))===0||i===points.length-1)svg+=`<text x="${x(i)}" y="${H-16}" text-anchor="middle">${new Date(p.date).toLocaleDateString('en-GB',{day:'2-digit',month:'short'})}</text>`;});
 return `<article class="chart-card cumulative-card"><div class="chart-heading"><div><h3>Cumulative ticket evolution by cohort</h3><p>Number of Jira tickets in each donut cohort over time · reconstructed from ticket creation history</p></div><label class="cumulative-range">Time frame<select id="cumulative-range"><option value="all" ${range==='all'?'selected':''}>All ticket history</option><option value="30" ${range==='30'?'selected':''}>Last 30 days</option><option value="90" ${range==='90'?'selected':''}>Last 90 days</option><option value="180" ${range==='180'?'selected':''}>Last 180 days</option></select></label><span class="asof-chip">${points.length} weekly point${points.length===1?'':'s'}</span></div><div class="cumulative-scroll"><svg class="cumulative-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Cumulative Jira ticket count over time for Host SW features, Requirements, Dev. Spec. Documents and Validation plan">${svg}</svg></div><div class="chart-key">${cohorts.map(([k,label],j)=>`<span><i style="background:${seriesColors[j]}"></i>${label}</span>`).join('')}</div><p class="chart-footnote">Each point counts tickets returned by Jira filter 19455 whose creation date is on or before that week. Workbook snapshots are excluded.</p></article>`;
}
function deadlinesChart(rows){
 const d=Analytics.dueSummary(rows,state.dueField,state.asOf),max=Math.max(1,...d.months.map(m=>m.total));
 return `<div class="chart-heading"><div><h3>Delivery calendar</h3><p>Due dates by month · ${rows.length-d.missing} dated supporting entries</p></div><label><span class="sr-only">Deadline milestone</span><select id="deadline-field"><option value="due" ${state.dueField==='due'?'selected':''}>Feature Done target</option><option value="preDue" ${state.dueField==='preDue'?'selected':''}>Pre-silicon due</option></select></label></div><div class="deadline-toolbar"><label>As of <input id="as-of" type="date" value="${state.asOf}"></label><span>${d.missing} without a usable date</span></div><div class="month-scroll"><div class="month-chart">${d.months.map(m=>`<button class="month-column" data-drill-field="dueMonth" data-drill-value="${m.month}" aria-label="${m.month}: ${m.total} supporting entries, ${m.confirmed} milestone confirmed"><strong>${m.total}</strong><span class="month-space"><span class="month-stack" style="height:${m.total/max*150}px"><i class="unconfirmed" style="flex:${m.unconfirmed}"></i><i class="confirmed" style="flex:${m.confirmed}"></i></span></span><span>${new Date(m.month+'-15T12:00:00').toLocaleDateString('en-GB',{month:'short'})}</span><small>${m.month.slice(0,4)}</small></button>`).join('')||'<p class="empty-chart">No usable due dates in this selection.</p>'}</div></div><div class="chart-key"><span><i style="background:#137e78"></i>Milestone confirmed</span><span><i style="background:#9daed0"></i>Completion unconfirmed</span></div><button class="date-attention" data-attention="past">${d.past.length} past due date with completion unconfirmed <span>View supporting entries →</span></button><p class="chart-footnote">Counts use workbook statuses, not live Jira. For pre-silicon, P-D and Done confirm completion; for B0, only Done does.</p>`;
}
function documentMatrix(){const docs=data.rows.filter(Analytics.scopes.docs.match),groups=Analytics.groupRows(docs,'group');return `<div class="chart-heading"><div><h3>Development specification matrix</h3><p>Supporting workbook · ${docs.length} document entries · click a recorded document for details</p></div><button class="text-button" data-cohort="docs">View documents →</button></div><div class="table-scroll"><table class="doc-matrix"><thead><tr><th>Component / document group</th><th>SRS</th><th>SAD</th><th>SUD</th><th>Other</th></tr></thead><tbody>${groups.map(g=>`<tr><th scope="row">${esc(g.label)}<span class="subline">${[...new Set(g.rows.map(r=>r.team).filter(Boolean))].map(esc).join(' / ')}</span></th>${['SRS','SAD','SUD','Other'].map(t=>{const list=g.rows.filter(r=>Analytics.docType(r.title)===t);return `<td>${list.map(r=>`<button data-row="${r.row}" class="matrix-status" title="${esc(r.title)} · ${esc(r.key)}">${badge(r)}<small>${esc(r.key)||'Source '+r.row}</small></button>`).join('')||'<span class="no-doc">No entry</span>'}</td>`}).join('')}</tr>`).join('')}</tbody></table></div><p class="chart-footnote">SRS: requirements · SAD: architecture · SUD: unit design. “No entry” means no matching master-plan representation in this section; it does not establish that a document is missing.</p>`}
function renderDashboard(rows){const areaKey=new Set(rows.map(r=>r.section)).size>1?'section':'group',shown=['focus','req','docs','validation'].flatMap(jiraIssuesForMode).length,outside=Math.max(0,(jiraScope.issues||[]).length-shown);return `<div class="visual-dashboard">${intelligenceBanner()}<div class="dashboard-section-heading"><h3>Jira ticket overview</h3><p>Filter 19455 · ${outside} ticket${outside===1?'':'s'} outside these cohorts · select a cohort for supporting detail</p></div><div class="cohort-grid">${['focus','req','docs','validation'].map(mode=>`<article class="chart-card cohort ${state.mode===mode?'current':''}"><div class="chart-heading"><button data-cohort="${mode}" class="cohort-title">${Analytics.scopes[mode].title} <span>↗</span></button></div><p class="cohort-subtitle">${Analytics.scopes[mode].subtitle}</p>${statusDonut(data.rows.filter(Analytics.scopes[mode].match),mode)}</article>`).join('')}</div><div class="dashboard-section-heading selected-scope"><h3>Ticket scope: ${esc(Analytics.scopes[state.mode].title)}</h3><p>${jiraIssuesForMode(state.mode).length} Jira tickets in this cohort</p></div>${cumulativeCohortChart()}<div class="dashboard-section-heading selected-scope"><h3>Supporting master-plan representation</h3><p>Workbook entries add planning context and never change Jira ticket counts</p></div>${smallLegend()}<div class="analysis-grid"><article class="chart-card"><div class="chart-heading"><div><h3>Supporting master-plan status by ${areaKey==='section'?'feature area':'component'}</h3><p>Supporting entries · recorded source statuses</p></div></div><div class="bar-list">${stackedBars(rows,areaKey)}</div></article><article class="chart-card"><div class="chart-heading"><div><h3>Supporting master-plan team ownership</h3><p>Supporting entries by team</p></div></div><div class="bar-list">${stackedBars(rows,'team')}</div></article><article class="chart-card deadline-card">${deadlinesChart(rows)}</article><article class="chart-card"><div class="chart-heading"><div><h3>Supporting master-plan assignee distribution</h3><p>Supporting entry counts, including entries without an assignee</p></div></div><div class="bar-list owner-bars">${stackedBars(rows,'owner')}</div></article><article class="chart-card matrix-card">${documentMatrix()}</article></div><p class="chart-footnote dashboard-source">Authoritative scope: <a href="https://bos-semi.atlassian.net/issues/?filter=19455" target="_blank" rel="noopener noreferrer">Jira filter 19455 ↗</a>. Ticket status charts use Jira issue histories. Workbook charts below them provide planning context.</p></div>`;}
document.addEventListener('click',e=>{
 const cohort=e.target.closest('[data-cohort]'),drill=e.target.closest('[data-drill-field]'),attention=e.target.closest('[data-attention]');
 if(cohort){e.preventDefault();Object.assign(state,{mode:cohort.dataset.cohort,category:'',query:'',team:'',status:cohort.dataset.drillStatus||'',section:'',owner:'',group:'',dueMonth:'',attention:'',page:0,view:'register'});controls();render();document.querySelector('.workspace').scrollIntoView({block:'start'});}
 if(drill){e.preventDefault();const key=drill.dataset.drillField;if(['section','group','team','owner','dueMonth'].includes(key)){state[key]=drill.dataset.drillValue;if(drill.dataset.drillStatus)state.status=drill.dataset.drillStatus;state.page=0;state.view='register';controls();render();}}
 if(attention){state.attention='past';state.page=0;state.view='register';controls();render();}
});
document.addEventListener('change',e=>{if(e.target.matches('[data-jira-range]')){historyState.cumulativeRange=e.target.value;render()}if(e.target.id==='deadline-field'){state.dueField=e.target.value;state.dueMonth='';state.attention='';render()}if(e.target.id==='as-of'&&Analytics.isDate(e.target.value)){state.asOf=e.target.value;render()}});
